using System.Numerics;
using System.Reflection;
using ByteEngine.Core;
using ByteEngine.Core.InputSystem;
using ByteEngine.Core.Gameplay;
using ByteEngine.Core.Graphics;
using ByteEngine.Core.Scene;
using KarlsonDemo.Plugin;
internal static class MiningMachineMenuCheck
{
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS MACHINE MENU "+label);}
 public static void Run(Scene s,MiningOperation3D op)
 {
  var hash=System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(Program.Root+"/Scenes/Main.bytescene"));var host=new SceneManager();host.LoadScene(s);var ui=s.GameObjects.SelectMany(o=>o.Components).OfType<MiningBusinessUi3D>().Single();var trade=op.GameObject.GetComponent<MiningTrade3D>()!;var player=s.FindGameObject(op.PlayerObjectId)!;
  void Set(object o,string name,object value)=>o.GetType().GetProperty(name)!.SetValue(o,value);
  void Frame(bool mouse=false,Vector2? point=null){var raw=new RawInputSnapshot();if(mouse)raw.MouseButtonsDown.Add(MouseButton.Left);typeof(Input).GetMethod("UpdatePortable",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[raw,true]);typeof(Input).GetMethod("SetGameInputCaptured",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[true]);Input.SetGameViewPointer((point??new(640,360))/new Vector2(1280,720),new(1280,720),true);typeof(Time).GetMethod("Update",BindingFlags.NonPublic|BindingFlags.Static)!.Invoke(null,[.05d]);typeof(Scene).GetMethod("UpdateInternal",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(s,null);}
  UiWidget Widget(Guid id)=>s.FindGameObject(id)!.GetComponent<UiWidget>()!;
  void Click(Guid id){Frame();var w=Widget(id);Check(w.Visible&&w.Interactable,"native button is available: "+w.GameObject.Name);var r=UiLayout.Resolve(w.GameObject,w.Anchor,w.Offset,w.Size,new(1280,720));Frame(true,r.Position+r.Size/2);Frame();}
  Frame();player.Transform.WorldPosition=s.FindGameObject(ui.TerminalObjectId)!.Transform.WorldPosition+new Vector3(0,0,-1);Set(op,"Credits",50000);Set(op,"RawOre",80);Set(op,"RefinedOre",40);
  ui.Open(MiningScreen.Refinery);Frame();int level=op.RefineryLevel;Click(ui.Row0ButtonObjectId);Check(op.RefineryLevel==level+1,"refinery batch upgrade buys once through its visible hitbox");Click(ui.Row1ButtonObjectId);Click(ui.Row2ButtonObjectId);Check(op.RefinerySpeedLevel>0&&op.RefineryYieldLevel>0,"all three refinery upgrades are connected");Click(ui.PrimaryButtonObjectId);Check(op.RefiningAmount>0&&ui.Screen==MiningScreen.None,"Refine & Return starts real processing and closes immediately");ui.Open(MiningScreen.Refinery);Frame();Check(!Widget(ui.PrimaryButtonObjectId).Interactable,"active refinery cannot start a duplicate batch");float before=op.RefiningProgress;for(int i=0;i<5;i++)Frame();Check(op.RefiningProgress>before,"refinery progress advances while menu stays open");ui.Close();op.Tick(20);
  ui.Open(MiningScreen.AmmoPress);Frame();Check(!Widget(ui.PrimaryButtonObjectId).Visible,"ammo press keeps walk-up collection and no Collect button");int output=trade.OutputLevel;Click(ui.Row0ButtonObjectId);Click(ui.Row1ButtonObjectId);Click(ui.Row2ButtonObjectId);Check(trade.OutputLevel==output+1&&trade.StorageLevel>0&&trade.EfficiencyLevel>0,"ammo press upgrades all production parameters");ui.Close();
  ui.Open(MiningScreen.Company);Frame();Check(ui.Screen==MiningScreen.Research,"tent opens directly to upgrade hub");Check(ui.ResearchButtonObjectIds.Any(id=>Widget(id).Visible),"upgrade map exposes selectable nodes inside compact terminal");int rootIndex=trade.Research.ToList().FindIndex(n=>n.Id=="company");int oldRank=trade.ResearchRank("company");Click(ui.ResearchButtonObjectIds[rootIndex]);Click(ui.PrimaryButtonObjectId);Check(trade.ResearchRank("company")==oldRank+1,"clicking a map tile and Unlock purchases the selected permanent upgrade once");Click(ui.SecondaryButtonObjectId);Check(ui.Screen==MiningScreen.Market,"Market tab switches directly without an intermediary menu");Click(ui.RawButtonObjectId);Check(!ui.RefinedSelected,"Raw tab selects the actual raw cargo");Click(ui.RefinedButtonObjectId);Check(ui.RefinedSelected,"Refined tab selects actual refined cargo");var slider=Widget(ui.QuantitySliderObjectId);var rect=UiLayout.Resolve(slider.GameObject,slider.Anchor,slider.Offset,slider.Size,new(1280,720));Frame();Frame(true,rect.Position+rect.Size*.5f);Frame();Check(Math.Abs(ui.Quantity-trade.Stock(true)*.5f)<=1,"quantity slider uses the full visible track");int credit=op.Credits;Click(ui.PrimaryButtonObjectId);Check(trade.SaleInProgress&&!Widget(ui.PrimaryButtonObjectId).Interactable,"sale starts and prevents double orders");trade.Tick(20);Frame();Check(!trade.SaleInProgress&&op.Credits>credit,"shipment progress completes and awards real credits");Click(ui.SecondaryButtonObjectId);Check(ui.Screen==MiningScreen.Research,"Upgrades tab returns directly to research");ui.Close();
  Set(op,"RawOre",0);Set(op,"RefinedOre",0);ui.Open(MiningScreen.Drill);Frame();Click(ui.Contract2ButtonObjectId);Check(op.SelectedContractId==op.PreviewContract(2)!.Id,"drill card selects the displayed extraction contract");Click(ui.PrimaryButtonObjectId);Check(op.Phase==MiningPhase.Drilling&&ui.Screen==MiningScreen.None,"Start Extraction launches the selected wave and returns to gameplay");Check(player.GetComponent<PlayerController3D>()!.Enabled&&!Input.IsUiPointerRequested,"closing the panel restores movement and camera capture");host.UnloadScene();Check(hash.SequenceEqual(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(Program.Root+"/Scenes/Main.bytescene"))),"checks preserve authored scene and player saves");
 }
}
